/// <summary>
/// Contract class for document posting 
/// </summary>
[DataContractAttribute]
public class METSalesDocumentPostingDataContract extends METSysOperationServiceBaseDataContract
{
    container       conShipmentId;
    container       conDocStatus;
    container       conAccountOrder;
    DocumentStatus  docStatus;
    WHSShipmentId   shipmentId;
    AccountOrder    accountOrder;

}

Method.Source:
/// <summary>
/// Method to return list of shipmentId
/// </summary>
/// <param name = "_conShipmentId">container</param>
/// <returns> returns list of shipmentId</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public container parmShipmentIdList(container  _conShipmentId = conShipmentId)
{
    conShipmentId = _conShipmentId;

    return conShipmentId;
}

/// <summary>
/// Method to return list of document status
/// </summary>
/// <param name = "_conDocStatus">container</param>
/// <returns> returns list of document status</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public container parmDocStatusList(container  _conDocStatus = conDocStatus)
{
    conDocStatus = _conDocStatus;

    return conDocStatus;
}

/// <summary>
/// Method to return list of account order
/// </summary>
/// <param name = "_conAccountOrder">container</param>
/// <returns> returns list of account order</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public container parmAccountOrderList(container  _conAccountOrder = conAccountOrder)
{
    conAccountOrder = _conAccountOrder;

    return conAccountOrder;
}

/// <summary>
/// Method to return document status
/// </summary>
/// <param name = "_docStatus">DocumentStatus</param>
/// <returns> returns document status</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public DocumentStatus parmDocStatus(DocumentStatus  _docStatus = docStatus)
{
    docStatus = _docStatus;

    return docStatus;
}

/// <summary>
/// Method to return shipmentId
/// </summary>
/// <param name = "_shipmentId">WHSShipmentId</param>
/// <returns> returns shipmentId</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public WHSShipmentId parmShipmentId(WHSShipmentId  _shipmentId = shipmentId)
{
    shipmentId = _shipmentId;

    return shipmentId;
}

/// <summary>
/// Method to return account order
/// </summary>
/// <param name = "_accountOrder">AccountOrder</param>
/// <returns> returns account order</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public AccountOrder parmAccountOrder(AccountOrder  _accountOrder = accountOrder)
{
    accountOrder = _accountOrder;

    return accountOrder;
}
